sources.a.js:
export function summarize({ values }) {
  return { total: values.reduce((sum, value) => sum + value, 0) };
}

sources.b.js:
import { summarize } from './a.js';
export const show = values => summarize(values, 'total').toFixed(1);
export const preview = values => summarize(values, 'total').toFixed(0);
